package com.lamggm.rospocket;
import android.graphics.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class OperatorCanvasTest {
 @Test public void floatingPlusUsesHighContrastInkOnItsAccentFill(){android.content.Context c=RuntimeEnvironment.getApplication();UiTheme.save(c,"dark");VisualButton v=new VisualButton(c,"fab","add");v.setText("+");v.measure(View.MeasureSpec.makeMeasureSpec(80,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(80,View.MeasureSpec.EXACTLY));v.layout(0,0,80,80);Bitmap b=Bitmap.createBitmap(80,80,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));int dark=0;for(int y=0;y<80;y++)for(int xx=0;xx<80;xx++){int p=b.getPixel(xx,y);if(Color.alpha(p)==255&&Color.red(p)<80&&Color.green(p)<100&&Color.blue(p)<90)dark++;}assertTrue("Floating plus must use opaque dark ink on the light accent",dark>12);b.recycle();}
 @Test public void trailDrawsObservedSegmentsButDoesNotBridgeMissingTf()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();UiTheme.save(c,"dark");LocationMapView v=new LocationMapView(c);byte[] cells=new byte[400];v.map(new SensorPacket(MapPacketTest.packet(MapPacketTest.meta().put("width",20).put("height",20).put("resolution",.5).put("originX",-5).put("originY",-5),cells)).decode().map);v.measure(View.MeasureSpec.makeMeasureSpec(300,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(300,View.MeasureSpec.EXACTLY));v.layout(0,0,300,300);long d=System.nanoTime()+10000000000L;v.pose(-3,0,0,d);v.pose(-1,0,0,d);v.clearPose();v.pose(1,0,0,d);v.pose(3,0,0,d);v.clearPose();Bitmap b=Bitmap.createBitmap(300,300,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));float[] yes=v.screen(-2,0),no=v.screen(0,0);assertEquals(LocationMapView.TRAIL_COLOR,b.getPixel((int)yes[0],(int)yes[1]));assertNotEquals(LocationMapView.TRAIL_COLOR,b.getPixel((int)no[0],(int)no[1]));b.recycle();v.trailEnabled(false);assertEquals(0,v.trailSize());}
}
